  assert.ok(/,S,,0,0,0,,x$/.test(shown[0][0]) && shown[1][0].startsWith("Dialogue: 0,0:00:00.00,") && /,y$/.test(shown[1][0]), `narration subtitles burned per part, each part's times start at 0: ${shown.flat().join(" | ")}`);
