  d.script = { outputs: [{ id: "o1", kind: "long", lang: "vi", title: [], sections: [{ id: "a", role: "body", chapter: "Chương 1", text: "x y", shots: [], cues: [{ segment: "s1", text: "x" }, { segment: "s2", text: "y" }] }, { id: "b", role: "ending", text: "z", shots: [], cues: [{ segment: "s3", text: "z" }] }] }] };
